<script setup>
import {computed,useId} from 'vue';
const id=useId();const props=defineProps({type:{default:'line'},color:{default:'#b1d294'},values:{default:()=>[24,32,28,48,43,59,54,67,64,78,72,86]},compare:Boolean,labels:{default:()=>['00:00','04:00','08:00','12:00','16:00','20:00']}});
const max=computed(()=>Math.max(...props.values)*1.16);const y=v=>132-v/max.value*112;const x=i=>28+i*(294/(props.values.length-1));const path=computed(()=>props.values.map((v,i)=>`${i?'L':'M'}${x(i)} ${y(v)}`).join(' '));
</script>
<template><svg viewBox="0 0 338 157" class="mini-chart" role="img" :aria-label="type==='bar'?'产量柱形图':'数据趋势图'"><defs><linearGradient :id="id" x1="0" y1="0" x2="0" y2="1"><stop :stop-color="color" stop-opacity=".25"/><stop offset="1" :stop-color="color" stop-opacity="0"/></linearGradient></defs><g fill="none" stroke="currentColor" opacity=".13" stroke-dasharray="2 4"><path d="M28 20H326M28 57H326M28 95H326M28 132H326"/></g><g fill="currentColor" opacity=".6" font-size="9" font-family="monospace"><text x="0" y="24">{{Math.round(max)}}</text><text x="3" y="61">{{Math.round(max*.66)}}</text><text x="3" y="99">{{Math.round(max*.33)}}</text><text x="14" y="136">0</text><text v-for="(l,i) in labels" :x="24+i*294/(labels.length-1)" y="152" :text-anchor="i===labels.length-1?'end':'start'">{{l}}</text></g><template v-if="type==='line'"><path :d="path+' L322 132H28Z'" :fill="`url(#${id})`"/><path v-if="compare" d="M28 121L55 110L81 117L108 105L135 99L162 109L188 79L215 86L242 64L268 86L295 67L322 57" stroke="currentColor" opacity=".35" stroke-width="1.4" stroke-dasharray="4 4" fill="none"/><path :d="path" fill="none" :stroke="color" stroke-width="2"/><circle v-for="(v,i) in values" :cx="x(i)" :cy="y(v)" r="2.3" :fill="color"><title>{{i+1}} · {{v}}</title></circle></template><template v-else><g v-for="(v,i) in values"><rect :x="28+i*(294/values.length)" :y="y(v)" :width="294/values.length*.6" :height="132-y(v)" :fill="color" :opacity=".32+i/values.length*.6"/><path :d="`M${28+i*294/values.length} ${y(v)}h${294/values.length*.6}`" :stroke="color" stroke-width="2"/><title>{{i+1}} · {{v}}</title></g></template></svg></template>
